private displayLeaderboard() {
  const yOff = (this.scale.height - 600) / 2;
  const cx = this.scale.width / 2;
  const startY = 163 + yOff;
  const lineHeight = 35;
  const ICON_SIZE = 26;
  const ICON_X = 20;

  // 헤더
  const headerText = this.add.text(cx + 14, startY, '순위   이름     점수', {
    fontSize: '16px',
    color: '#ffff00',
    fontStyle: 'bold',
    stroke: '#000',
    strokeThickness: 4
  }).setOrigin(0.5);
  this.leaderboardTexts.push(headerText);

  // 랭킹 데이터 표시
  if (this.leaderboardData.length === 0) {
    const noDataText = this.add.text(cx, startY + 50, '아직 랭킹이 없습니다\n\n첫 번째 플레이어가 되어보세요!', {
      fontSize: '18px',
      color: '#ccc',
      stroke: '#000',
      strokeThickness: 3,
      align: 'center'
    }).setOrigin(0.5);
    this.leaderboardTexts.push(noDataText);
    return;
  }

  this.leaderboardData.forEach((entry, index) => {
    const y = startY + 30 + (index * lineHeight);

    // 순위별 색상
    let color = '#ffffff';
    if (entry.rank === 1) color = '#FFD700';
    else if (entry.rank === 2) color = '#C0C0C0';
    else if (entry.rank === 3) color = '#CD7F32';

    // 캐릭터 아이콘
    const charDef = CHARACTERS.find(c => c.id === (entry.characterType ?? 'chibi')) ?? CHARACTERS[0];
    const icon = this.add.image(ICON_X, y, charDef.imageKey)
      .setDisplaySize(ICON_SIZE, ICON_SIZE)
      .setOrigin(0.5);
    this.leaderboardTexts.push(icon);

    const rankText = `${entry.rank}`.padEnd(7, ' ');
    const nameText = entry.userName.padEnd(8, ' ');
    const scoreText = entry.score.toString().padStart(6, ' ');

    const text = this.add.text(
      cx + 14,
      y,
      `${rankText}${nameText}${scoreText}`,
      {
        fontSize: '16px',
        color: color,
        fontFamily: 'monospace',
        stroke: '#000',
        strokeThickness: 3
      }
    ).setOrigin(0.5);

    this.leaderboardTexts.push(text);
  });
}

/** 이번 달 말일까지 남은 일수 */
private calcDaysUntilMonthEnd(): number {
  const now = new Date();
  const lastDay = new Date(now.getFullYear(), now.getMonth() + 1, 0);
  const diff = lastDay.getTime() - now.getTime();
  return Math.max(0, Math.ceil(diff / (1000 * 60 * 60 * 24)));

